// Demo program for: VirtualBox (virtualization software)
// Public record -- VirtualBox, VMware, Hyper-V — the complete database of virtualization tools.
// Run it with: node demo.js   (works as-is on any PC with Node.js)
const record = {
  id: "JAH-VIRT-000001",
  title: "VirtualBox",
  kind: "virtualization software",
  developer: "Oracle",
  platforms: "Windows, macOS, Linux",
  license: "Open source"
};
function demo() {
  console.log("=== " + record.title + " ===");
